#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
case "${1:-}" in
  --help|-h)
    printf '%s\n' 'bash scripts/setup-enrichment.sh [--help|--check]' \
      'Five desktop stages: Vulkan prerequisites, model/server, private endpoint configuration, GitHub auth, and a first reviewed fill.' \
      '--check only lists installed commands; it writes nothing, installs nothing and opens no browser.' \
      'Interactive values are saved to .env.enrichment.local (0600, ignored by git). See docs/desktop-enrichment.md.'
    return ;;
  --check)
    local tool missing=0
    for tool in pacman vulkaninfo llama-server node pnpm curl gh; do
      if command -v "$tool" >/dev/null 2>&1; then printf 'found: %s\n' "$tool"
      else printf 'missing: %s\n' "$tool"; missing=1; fi
    done
    return "$missing" ;;
  '') ;;
  *) printf '%s\n' 'Unknown option; use --help.' >&2; return 1 ;;
esac

local root model_command
root=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)
cd "$root"
ENV_FILE="$root/.env.enrichment.local"
[[ ! -L "$ENV_FILE" ]] || { warn 'Private environment file must not be a symlink.'; return 1; }
umask 077
touch "$ENV_FILE"
chmod 600 "$ENV_FILE"
TOTAL_STAGES=5
banner 'Desktop recipe enrichment'

stage 'Desktop prerequisites and Vulkan'
open_url 'https://archlinux.org/packages/extra/x86_64/ggml-vulkan/'
say 'Run this on the Omarchy/Arch desktop with the RX 9070 XT.'
command -v pacman >/dev/null 2>&1 || { warn 'This setup path requires Arch pacman. See the docs for other servers.'; return 1; }
if confirm 'Install/update the Arch packages with sudo pacman?'; then
  sudo pacman -Syu --needed llama-cpp ggml-vulkan vulkan-radeon vulkan-tools
fi
for tool in vulkaninfo llama-server node pnpm gh; do
  command -v "$tool" >/dev/null 2>&1 || { warn "Missing $tool; install it using the desktop toolchain, then rerun."; return 1; }
done
vulkaninfo --summary
llama-server --list-devices
say 'Confirm these list the Radeon, not only a CPU or software renderer.'
confirm 'Does Vulkan list the RX 9070 XT?' || return 1

stage 'Choose a candidate and start its server'
open_url 'https://huggingface.co/Qwen/Qwen3-4B-GGUF/tree/main'
open_url 'https://huggingface.co/Qwen/Qwen3-8B-GGUF/tree/main'
say 'Compare the publisher Q4_K_M files. Check the license and note the exact revision and file.'
say 'Download one candidate in the desktop browser. Neither candidate is a measured winner.'
ask ENRICH_MODEL_FILE 'Absolute path to the downloaded GGUF:'
[[ "$ENRICH_MODEL_FILE" == /* && -f "$ENRICH_MODEL_FILE" ]] || { warn 'Choose an existing absolute GGUF path.'; return 1; }
write_env ENRICH_MODEL_FILE "$ENRICH_MODEL_FILE"
ask ENRICH_MODEL_IDENTITY 'Model repository/revision, filename and quantization:'
[[ -n "$ENRICH_MODEL_IDENTITY" ]] || return 1
write_env ENRICH_MODEL_IDENTITY "$ENRICH_MODEL_IDENTITY"
llama-server --version
ask ENRICH_SERVER_VERSION 'Copy the installed llama.cpp version/build identity:'
[[ -n "$ENRICH_SERVER_VERSION" ]] || return 1
write_env ENRICH_SERVER_VERSION "$ENRICH_SERVER_VERSION"
printf -v model_command 'llama-server -m %q --alias vegdex-enrich --host 127.0.0.1 --port 8080 --n-gpu-layers 99 --ctx-size 16384 --chat-template-kwargs %q' "$ENRICH_MODEL_FILE" '{"enable_thinking":false}'
say 'Run this in a separate terminal and leave it running until the fill finishes (batches need the larger context):'
say "$model_command"
note 'Check llama-server --help if your Arch package lacks a flag. See upstream build fallback in the docs.'
say 'Wait for loading to finish. Read the startup logs for Radeon GPU layer offload and actual memory use.'
confirm 'Does the server show successful GPU offload without running out of memory?' || return 1

stage 'Configure the private endpoint'
open_url 'https://github.com/ggml-org/llama.cpp/blob/master/tools/server/README.md'
say 'Local server: base URL http://127.0.0.1:8080/v1 and model vegdex-enrich.'
ask ENRICH_BASE_URL 'OpenAI-compatible base URL (include /v1):'
ask ENRICH_MODEL 'Advertised model ID:'
if confirm 'Does this endpoint require an API key?'; then
  ask_secret ENRICH_API_KEY 'API key (hidden):'
else
  ENRICH_API_KEY=''
fi
write_env ENRICH_BASE_URL "$ENRICH_BASE_URL"
write_env ENRICH_MODEL "$ENRICH_MODEL"
write_env ENRICH_API_KEY "$ENRICH_API_KEY"
export ENRICH_BASE_URL ENRICH_MODEL ENRICH_API_KEY
# shellcheck disable=SC2016 # JavaScript template expressions, not shell expansion.
if ! node --input-type=module -e '
  try {
    const url = new URL(process.env.ENRICH_BASE_URL);
    if (!["http:", "https:"].includes(url.protocol) || url.username || url.password || url.search || url.hash) throw new Error();
    const response = await fetch(`${url.href.replace(/\/$/, "")}/models`, { headers: process.env.ENRICH_API_KEY ? { authorization: `Bearer ${process.env.ENRICH_API_KEY}` } : {}, signal: AbortSignal.timeout(10000) });
    if (!response.ok) throw new Error();
    console.log("Endpoint models check passed.");
  } catch { console.error("Endpoint models check failed; check server readiness and configuration."); process.exitCode = 1; }
'; then
  note 'Some compatible providers omit GET /models. The first fill tests the required chat endpoint.'
  confirm 'Continue anyway?' || return 1
fi

stage 'Authenticate GitHub'
open_url 'https://cli.github.com/manual/gh_auth_login'
say 'The fill reads the crawl store from the data release of antomanc/vegdex. Read access is enough.'
if ! gh auth status >/dev/null 2>&1; then
  say 'Run gh auth login in a separate terminal. Complete the browser/device sign-in there.'
  pause 'Press Enter after authentication'
fi
gh auth status >/dev/null 2>&1 || { warn 'GitHub authentication is not ready.'; return 1; }

stage 'Run a first fill and review it'
say 'A small batch of Italian names goes to the model; every answer is checked before it reaches data/vocab/.'
confirm 'Run one batch of 20 now?' || return 0
pnpm enrich --kind name --lang it --size 20 --batches 1
git diff --stat -- packages/ingest/data/vocab
say 'Read the diff: every name should be what an Italian cook would buy, with the right plural and gender.'
say 'Discard a bad run with: git checkout -- packages/ingest/data/vocab'
say 'Larger runs and landing them as a PR: docs/agents/vocabulary.md.'
finish
}

run_wizard "$@"; exit
